schemas.ddl:
CREATE TABLE materials (
  id int8 NOT NULL,
  shared_feature timestamptz,
  size int4,
  pending_customer date NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE permissions (
  id int8 NOT NULL,
  employee int8,
  zone text,
  historical_release int8,
  default_feature bool NOT NULL,
  public_transaction int8 NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE roles (
  id int8 NOT NULL,
  host uuid NOT NULL,
  batch int4,
  artifact uuid NOT NULL,
  PRIMARY KEY (id)
);

ALTER TABLE roles ADD CONSTRAINT fk_roles_batch FOREIGN KEY (batch) REFERENCES permissions (id) ON DELETE SET NULL ON UPDATE NO ACTION;

CREATE INDEX ix_permissions_historical_release_x0 ON permissions (historical_release);

CREATE INDEX ix_roles_batch ON roles (batch);
